    /// @dev Quotes burn, gross input, and fee for exact-output redemption.
    function _quoteRedeemExactOutput(
        address collateralToken,
        uint256 collateralAmount,
        uint8 decimals,
        uint16 redeemFeeBps,
        uint256 collateralIn,
        uint256 ftUSDMinted
